A = (2,5);
B = (0,0);
C = (9,0);
D = (B + C)/2;
E = (A + C)/2;
F = (A + B)/2;

draw(A--B--C--cycle);
draw(D--E--F--cycle);

label("$A$", A, N);
label("$B$", B, SW);
label("$C$", C, SE);
label("$D$", D, S);
label("$E$", E, NE);
